CREATE DATABASE IF NOT EXISTS pg_hostel CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci; USE pg_hostel;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','tenant') NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tenants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,full_name VARCHAR(120) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,phone VARCHAR(30),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_tenant_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rooms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,room_number VARCHAR(20) NOT NULL UNIQUE,floor SMALLINT NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS beds(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,room_id BIGINT UNSIGNED NOT NULL,label VARCHAR(20) NOT NULL,monthly_rent DECIMAL(10,2) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE KEY uq_bed_room_label(room_id,label),CONSTRAINT ck_bed_rent CHECK(monthly_rent>0),CONSTRAINT fk_bed_room FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE RESTRICT,INDEX idx_beds_active(room_id,is_active)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS allocations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,bed_id BIGINT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NULL,agreed_rent DECIMAL(10,2) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,active_tenant_id BIGINT UNSIGNED GENERATED ALWAYS AS (IF(end_date IS NULL,tenant_id,NULL)) STORED,active_bed_id BIGINT UNSIGNED GENERATED ALWAYS AS (IF(end_date IS NULL,bed_id,NULL)) STORED,UNIQUE KEY uq_active_tenant(active_tenant_id),UNIQUE KEY uq_active_bed(active_bed_id),INDEX idx_allocation_tenant_date(tenant_id,start_date),INDEX idx_allocation_bed_end(bed_id,end_date),CONSTRAINT ck_allocation_dates CHECK(end_date IS NULL OR end_date>=start_date),CONSTRAINT ck_allocation_rent CHECK(agreed_rent>0),CONSTRAINT fk_allocation_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE RESTRICT,CONSTRAINT fk_allocation_bed FOREIGN KEY(bed_id) REFERENCES beds(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rent_payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,allocation_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(10,2) NOT NULL,payment_date DATE NOT NULL,method ENUM('Cash','Bank transfer','UPI','Card','Other') NOT NULL,reference VARCHAR(100) NULL,rent_period CHAR(7) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_payment_reference(reference),INDEX idx_payment_period(rent_period,payment_date),INDEX idx_payment_allocation(allocation_id),CONSTRAINT ck_payment_amount CHECK(amount>0),CONSTRAINT ck_payment_period CHECK(rent_period REGEXP '^[0-9]{4}-(0[1-9]|1[0-2])$'),CONSTRAINT fk_payment_allocation FOREIGN KEY(allocation_id) REFERENCES allocations(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaints(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,category VARCHAR(80) NOT NULL,description TEXT NOT NULL,priority ENUM('Low','Medium','High','Urgent') NOT NULL DEFAULT 'Medium',status ENUM('Open','In Progress','Resolved') NOT NULL DEFAULT 'Open',resolution_notes TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,resolved_at TIMESTAMP NULL,INDEX idx_complaint_status(status,created_at),INDEX idx_complaint_tenant(tenant_id,created_at),CONSTRAINT fk_complaint_tenant FOREIGN KEY(tenant_id) REFERENCES tenants(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS maintenance_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,room_id BIGINT UNSIGNED NOT NULL,complaint_id BIGINT UNSIGNED NULL,description VARCHAR(500) NOT NULL,cost DECIMAL(10,2) NOT NULL DEFAULT 0,completed_on DATE NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT ck_maintenance_cost CHECK(cost>=0),CONSTRAINT fk_maintenance_room FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE RESTRICT,CONSTRAINT fk_maintenance_complaint FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE SET NULL) ENGINE=InnoDB;